function parseData(notify=false){
 if(busy())return records;
 const lines=$('#data').value.split(/\r?\n/).filter(l=>l.trim());
 records=lines.map((raw,i)=>{
  const cells=raw.split('|').map(s=>s.trim()), errors=[];
  if(cells.length!==8)return {line:i+1,errors:['Cần đúng 8 cột; hiện có '+cells.length+'.'],raw};
  const keys=['username','password','phone','name','bank','account','city','pin'],r={line:i+1,raw,errors,generated:[]};
  keys.forEach((k,j)=>r[k]=cells[j]);
  const ck=site+'|'+i+'|'+raw;
  if(!cache.has(ck))cache.set(ck,{});
  const generated=cache.get(ck);
  ['username','password','city','pin'].forEach(k=>{
   if(!r[k]&&profile().auto[k]){if(!generated[k])generated[k]=randField(k);r[k]=generated[k];r.generated.push(k);}
  });
  const need=mode==='register'?['username','password','phone','name']:mode==='bank'?(isOtpokvip()?['name','phone','bank','account','pin']:['name','bank','account','city','pin']):['username','password','phone','name','bank','account','city','pin'];
  const labels={username:'username',password:'mật khẩu',phone:'số điện thoại',name:'họ tên',bank:'mã ngân hàng',account:'số tài khoản',city:'thành phố',pin:'PIN rút'};
  need.filter(k=>!isOtpokvip()||k!=='city'&&(mode!=='register'||k!=='phone')).forEach(k=>{if(!r[k])errors.push('Thiếu '+labels[k]+'.');});
  if((mode!=='bank'||isOtpokvip())&&r.phone&&!/^\+?\d{8,15}$/.test(r.phone))errors.push('Số điện thoại cần có 8–15 chữ số.');
  r.bankInfo=lookup.get(norm(r.bank));
  if(mode!=='register'&&r.bank){if(!r.bankInfo)errors.push('Không nhận diện được mã bank “'+r.bank+'”.');else if(!r.bankInfo.IsBindEnabled)errors.push('Ngân hàng chưa hỗ trợ liên kết trong danh sách mẫu.');}
  if(mode!=='register'&&r.pin&&!/^\d+$/.test(r.pin))errors.push('PIN rút cần là chữ số.');
  if(isOtpokvip()&&mode!=='register'&&r.pin&&!/^\d{6}$/.test(r.pin))errors.push('otpokvip cần PIN rút gồm 6 chữ số.');
  return r;
 });
 renderRecords();renderOtpPinTools();renderTimeline();updateControls();
 if(notify)toast(records.length?records.some(r=>r.errors.length)?'Có dòng cần kiểm tra lại.':'Data hợp lệ. Đã chuẩn hóa mã ngân hàng.':'Chưa có data.');
 return records;
}
