function isQQ88(){return site==='qq88'||profile()?.flow==='qq88';}
function qqBankFor(r){return QQ_BANKS[r.bankInfo?.Id]||null;}
function bankMatches(r,text){const b=r.bankInfo,q=isQQ88()?qqBankFor(r):null;return [b?.Display,b?.Name,codes[b?.Id],q?.display,q?.code].filter(Boolean).some(name=>norm(name)===norm(text));}
let qqSaveConfirmed=false;
async function qqStep(id,r,token){
 if(id===3){await clickTarget('withdraw',token);await getTarget('addBank',token);return;}
 if(id===10){await clickTarget('addBank',token);return;}
 if(id===11){const el=await getTarget('bank',token);if(el.getAttribute('aria-disabled')==='true'||el.matches('input:disabled,select:disabled,button:disabled'))throw Error('Ô chọn ngân hàng chưa được website bật.');el.scrollIntoView({block:'center'});el.click();return;}
 if(id===12){const bank=qqBankFor(r);if(!bank)throw Error('QQ88 chưa có ngân hàng '+r.bankInfo.Display+' trong danh sách bạn gửi.');const selected=await until(()=>{const candidates=elements('[role="option"],mat-option,.mat-option-text,.am-picker-col-item,.am-list-item,.bank-item,.bank-list-item,[data-bank-code],span,div').filter(el=>bankMatches(r,el.textContent));return candidates.find(el=>!candidates.some(child=>child!==el&&el.contains(child)));},token,'ngân hàng '+bank.display);if(selected.getAttribute('aria-disabled')==='true')throw Error('Ngân hàng đang bị khóa trên QQ88.');selected.scrollIntoView({block:'center'});selected.click();await until(()=>{const current=target('bank');return current&&(bankMatches(r,current.textContent)||bankMatches(r,current.getAttribute('value')));},token,'xác nhận ngân hàng QQ88');return;}
 if(id===13){await enter('bankAccount',r.account,token);return;}
 if(id===14){await enter('city',r.city,token);let pair=await getPinPair(token);await enter('pin',r.pin,token,false,pair.first);pair=await getPinPair(token);await enter('pinConfirm',r.pin,token,false,pair.second);checkPinPair(pair,r.pin);return;}
 if(id===15){if(!cfg().saveBank){log('Đã điền ngân hàng và hai ô PIN; chưa bấm Xác nhận theo cấu hình.');return;}const account=await getTarget('bankAccount',token),city=await getTarget('city',token),pair=await getPinPair(token);checkPinPair(pair,r.pin);if(account.value!==r.account||city.value!==r.city)throw Error('Số tài khoản hoặc city trên trang chưa khớp data.');const at=performance.now();await clickTarget('saveBank',token,account.closest('form')||document);if(cfg().routes[2]){await verified(cfg().routes[2],at,token);qqSaveConfirmed=true;}else{log('Đã bấm Xác nhận trên QQ88. Kiểm tra thông báo kết quả của website.');}return;}
}
function resultDescription(){if(reviewManualSteps.length&&mode!=='register')return 'Đã đi qua quy trình kiểm tra có bước làm thủ công. '+(isOtpokvip()&&otpPhoneVerified?'Website đã xác nhận liên kết SĐT.':'Kiểm tra kết quả các bước làm thủ công trên website.');if(isOtpokvip()){if(mode==='register')return 'Đã điền tài khoản, mật khẩu và họ tên; chưa bấm Đăng ký.';return (otpBankClicked?'Đã bấm Xác Nhận ngân hàng. ':'Chưa xác nhận ngân hàng theo cấu hình. ')+(otpPhoneVerified?'Website đã xác nhận liên kết SĐT.':'Đã điền SĐT; chưa xác nhận liên kết.');}if(mode==='register')return 'Đã điền form; chưa bấm đăng ký.';if(!cfg().saveBank)return 'Đã điền thông tin ngân hàng; chưa bấm lưu.';if(isQQ88()&&!qqSaveConfirmed)return 'Đã bấm Xác nhận trên QQ88. Kiểm tra kết quả lưu ngân hàng trên website.';return 'Website đã xác nhận lưu ngân hàng.';}

let registrationActive=false,waitingCaptcha=false,captchaManualAck=0,captchaAcknowledged=false;
function captchaPresent(){
 const token=Array.from(document.querySelectorAll('textarea[name="g-recaptcha-response"],textarea[name="h-captcha-response"],input[name="cf-turnstile-response"]')).some(el=>el.value.trim());
 const challenges=elements('[data-viptool-captcha="challenge"],.geetest_panel,.geetest_popup_wrap,.yidun_popup,.yidun_modal,.captcha-modal,.captchaModal,.captcha-popup,.slider-captcha,.verifybox,iframe[src*="turing.captcha"],iframe[src*="captcha"][src*="challenge"],.nc_wrapper,.nc-container,.secsdk-captcha-drag-wrapper,iframe[src*="recaptcha"][src*="bframe"],iframe[src*="hcaptcha"][title*="challenge"],iframe[src*="turnstile"]');
 const active=challenges.some(el=>!el.matches('.nc-container:has(.nc-lang-cnt[data-nc-lang="_yesTEXT"])')&&!el.querySelector('.nc-lang-cnt[data-nc-lang="_yesTEXT"],.geetest_success_radar_tip_content'));
 if(active)return true;
 if(token)return false;
 if(elements('iframe[src*="recaptcha"][src*="anchor"],iframe[src*="hcaptcha"][title*="checkbox"],.g-recaptcha,.h-captcha').length)return true;
 const fields=elements('input[name="captcha"],input[name="checkCode"],input[formcontrolname="captcha"],input[formcontrolname="checkCode"]');
 return fields.some(el=>!el.value.trim());
}
function showCaptchaWait(on){waitingCaptcha=on;$('#captcha-banner').hidden=!on;if(on){$('#run-badge').textContent='Chờ CAPTCHA';$('#countdown').textContent='Chờ bạn giải CAPTCHA trên website; không giới hạn thời gian.';$('#footer-status').textContent='Chờ bạn giải CAPTCHA';$('.app').hidden=true;$('#shade').hidden=true;$('#launcher').hidden=false;$('#float-status').textContent='CAPTCHA';}else{updateControls();}}
async function captchaGate(token,force=false){if(!registrationActive||execution!=='live')return false;const present=captchaPresent();if(!present)captchaAcknowledged=false;if(!force&&(!present||captchaAcknowledged))return false;if(force)captchaAcknowledged=false;const ack=captchaManualAck;showCaptchaWait(true);log('Chờ người dùng tự giải CAPTCHA.');try{while(true){await wait(120,token);if(captchaManualAck!==ack){captchaAcknowledged=true;break;}if(!force&&!captchaPresent())break;if(force&&captchaPresent())force=false;}log('Đã kết thúc chờ CAPTCHA; tiếp tục kiểm tra đăng ký.');return true;}finally{if(token===runToken&&alive){showCaptchaWait(false);}}}
function isCaptchaError(message){return /cap\s*cha|captcha|check.?code|ma (?:xac nhan|xac minh|bao ve)|verification code|security verification/.test(words(message));}
async function registerWithCaptcha(token){registrationActive=true;captchaAcknowledged=false;try{while(true){await captchaGate(token);const at=performance.now();await clickTarget('register',token);try{await verified(cfg().routes[0]||routes[0],at,token,()=>!target('register')&&!!target('accountMenu'));return;}catch(error){if(error.message!=='VIPTOOL_CAPTCHA_RETRY')throw error;const latest=responses.filter(r=>r.path===(cfg().routes[0]||routes[0])&&r.at>=at).at(-1);if(latest?.ok)return;if(!target('register')&&target('accountMenu'))return;}}}finally{registrationActive=false;captchaAcknowledged=false;if(alive&&!isUnloading){showCaptchaWait(false);}}}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.id==='captcha-done')captchaManualAck++;if(b.id==='captcha-stop'){stop();waitingCaptcha=false;$('#captcha-banner').hidden=true;host.openDemo();}});
