 const fields=Object.values(OTP_REGISTER_FIELDS),names=elements('input[data-input-name="realName"]').filter(otpInputVisible),groups=[];
 for(const name of names){for(let parent=name.parentElement;parent;parent=parent.parentElement){const found=Object.fromEntries(fields.map(field=>[field,[...parent.querySelectorAll('input[data-input-name="'+field+'"]')].filter(otpInputVisible)]));if(fields.every(field=>found[field].length===1)){groups.push({element:parent,inputs:found});break;}if(parent===document.body)break;}}
 if(groups.length>1)throw Error('Có nhiều form đăng ký otpokvip đang hiển thị. Đóng form thừa rồi chạy lại.');
