  const custom=selector&&selector!==OTP_MAP.register?elements(selector,container).filter(otpInputVisible).filter(el=>!mapping?.text||words(el.textContent)===words(mapping.text)).map(el=>el.closest('button')||el):[];
  const candidates=[...new Set(custom.length?custom:[...container.querySelectorAll('button[id="insideRegisterSubmitClick"]')])].filter(button=>otpInputVisible(button)&&(scope===document||scope.contains(button)));
  if(candidates.length===1)return candidates[0];
