function otpFrontElement(el){const r=el.getBoundingClientRect();if(r.right<=0||r.left>=innerWidth||r.bottom<=0||r.top>=innerHeight)return false;const pointX=(Math.max(0,r.left)+Math.min(r.right,innerWidth))/2,pointY=(Math.max(0,r.top)+Math.min(r.bottom,innerHeight))/2;const top=document.elementsFromPoint(pointX,pointY).find(node=>node!==host&&!host.contains(node));return !!top&&(el===top||el.contains(top));}
